/*
 * A056603  Squarefree kernels of distinct values of lcm(1,...,m) (A051451).
 * https://oeis.org/A056603
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = radical( lcm(1,2,…,m) ) for the n‑th distinct value of
 *            lcm(1,2,…,m). The radical equals the product of all primes ≤ m.
 *            The sequence is generated by iterating through each integer m,
 *            multiplying the running product whenever a new prime appears,
 *            and recording that product whenever m is a pri...
 * Range:     u8 n <= 8, u16 n <= 11, u32 n <= 16, u64 n <= 23, u128 n <= 23,
 *            big any n
 * Helpers:   build_spf
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* The program uses the supplied helper build_spf()
   to obtain the smallest prime factor of every integer
   up to a current limit.  No other utilities are needed. */

#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include "../utils/build_spf.h"   /* build_spf */

static bool     initialized = false;   /* first call? */
static idx_t   current_m      = 1;     /* current integer m  */
static seq_t   current_rad    = 1;     /* product of all primes ≤ current_m */
static seq_t*  cache          = NULL;  /* cache of sequence values */
static size_t  cache_size     = 0;     /* number of values stored */
static size_t  cache_cap      = 0;     /* allocated capacity */
static idx_t   spf_limit      = 0;     /* highest m with an available spf table */
static idx_t*  spf            = NULL; /* smallest prime factor array */

/* Ensure that spf[0..limit] is available.  The table is
   allocated as an array of idx_t of size limit+1. */
static void ensure_spf(idx_t limit)
{
    if (limit <= spf_limit) return;
    /* free previous table if any */
    if (spf) free(spf);
    build_spf(limit, &spf);
    spf_limit = limit;
}

/* Check whether the number m is a prime power.
   (A prime power has exactly one distinct prime factor.) */
static bool is_prime_power(idx_t m)
{
    if (m <= 1) return false;
    idx_t p = spf[m];
    idx_t t = m;
    while (t % p == 0) t /= p;
    return t == 1;
}

/* Grow the cache to accommodate at least (new_cap) elements. */
static void grow_cache(size_t new_cap)
{
    if (new_cap <= cache_cap) return;
    size_t new_cap2 = new_cap * 2;
    seq_t* new_buf = (seq_t*)malloc(new_cap2 * sizeof(seq_t));
    for (size_t i = 0; i < cache_size; ++i) new_buf[i] = cache[i];
    free(cache);
    cache    = new_buf;
    cache_cap = new_cap2;
}

/* Generate sequence values up to (target-1) indices (0‑based). */
static void generate_up_to(idx_t target)
{
    if (target <= cache_size) return;          /* already have enough */

    /* lazy initialization */
    if (!initialized) {
        cache_cap = 32;
        cache     = (seq_t*)malloc(cache_cap * sizeof(seq_t));
        /* a(1) = 1 */
        cache[0] = (seq_t)1;
        cache_size = 1;
        /* start with m = 1; next m will be 2 */
        current_m = 1;
        current_rad = (seq_t)1;
        /* initial SPF table up to at least 2 */
        ensure_spf(2);
        initialized = true;
    }

    while (cache_size < target) {
        /* make sure SPF covers the next m */
        if (current_m + 1 > spf_limit) {
            idx_t new_lim = (spf_limit + 1) * 2;
            if (new_lim < current_m + 1) new_lim = current_m + 1;
            ensure_spf(new_lim);
        }
        ++current_m;                                   /* m = current_m */

        /* if m is prime, multiply the running radical */
        if (spf[current_m] == current_m) {
            current_rad *= (seq_t)current_m;
        }

        /* if m is a prime power, record the current radical */
        if (is_prime_power(current_m)) {
            grow_cache(cache_size + 1);
            cache[cache_size++] = current_rad;
        }
    }
}

/* Main entry point required by the framework. */
seq_t a(idx_t n)
{
    /* n is 1‑based; the cache index is n-1 */
    if (n == 0) return (seq_t)0;          /* undefined for offset 0 */
    generate_up_to(n);
    return cache[n - 1];
}
